import React, { useState } from 'react';
import axios from 'axios';

function App() {
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadStatus, setUploadStatus] = useState('');

  // Handle file selection
  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0]);
  };

  // Upload the file to the backend
  const uploadFile = async () => {
    if (!selectedFile) {
      setUploadStatus('Please select a file to upload.');
      return;
    }

    try {
      const formData = new FormData();
      formData.append('audio', selectedFile);

      // Ensure the backend is running and reachable at the right endpoint
      const response = await axios.post('http://localhost:5000/upload-audio', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      console.log('File uploaded successfully:', response.data);
      setUploadStatus('File uploaded successfully!');
    } catch (error) {
      console.error('Error uploading the audio file:', error);
      if (error.code === 'ERR_NETWORK') {
        setUploadStatus('Network error: Could not connect to the server.');
      } else {
        setUploadStatus('Error uploading the file. Please try again.');
      }
    }
  };

  return (
    <div className="App">
      <h1>Audio File Uploader</h1>

      {/* File input */}
      <input type="file" accept="audio/*" onChange={handleFileChange} />

      {/* Upload button */}
      <button onClick={uploadFile}>Upload Audio</button>

      {/* Display upload status */}
      {uploadStatus && <p>{uploadStatus}</p>}
    </div>
  );
}

export default App;
